# Spring Boot 3.2+
spring.threads.virtual.enabled=true

// WRONG: a fixed pool of virtual threads
Executors.newFixedThreadPool(50, Thread.ofVirtual().factory());

// RIGHT: unlimited virtual threads, limited access to the database
Semaphore dbPermits = new Semaphore(20);
executor.submit(() -> {
    dbPermits.acquire();
    try { return query(); } finally { dbPermits.release(); }
});
